<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { buscarEncargados, eliminarAlmacen, guardarAlmacen, listarAlmacenes, type Almacen, type PersonaAlmacen } from '../services/almacenes'
const rows=ref<Almacen[]>([]),criterio=ref(''),page=ref(1),lastPage=ref(1),total=ref(0),loading=ref(false),saving=ref(false),error=ref(''),success=ref(''),modal=ref(false),editing=ref<number|null>(null),personSearch=ref(''),people=ref<PersonaAlmacen[]>([]),selectedPerson=ref<PersonaAlmacen|null>(null)
const form=reactive({nombre:'',codigo_avalon:'',encargado_id:0,telefono:'',direccion:'',por_defecto:false,estado:true})
async function load(next=1){page.value=next;loading.value=true;error.value='';try{const r=await listarAlmacenes(criterio.value,next);rows.value=r.data;total.value=r.total;lastPage.value=r.last_page}catch(e){error.value=message(e)}finally{loading.value=false}}
function open(item?:Almacen){editing.value=item?.id||null;Object.assign(form,{nombre:item?.nombre||'',codigo_avalon:item?.codigo_avalon||'',encargado_id:item?.encargado_id||0,telefono:item?.telefono||'',direccion:item?.direccion||'',por_defecto:item?.por_defecto||false,estado:item?.estado??true});selectedPerson.value=item?{id:item.encargado_id,nombre:item.encargado,identificador:''}:null;personSearch.value='';people.value=[];modal.value=true}
async function searchPeople(){if(personSearch.value.trim().length<4){error.value='Ingrese al menos 4 caracteres para buscar al encargado.';return}try{people.value=await buscarEncargados(personSearch.value)}catch(e){error.value=message(e)}}
function choose(person:PersonaAlmacen){selectedPerson.value=person;form.encargado_id=person.id;people.value=[];personSearch.value=''}
function validate(){if(!form.nombre.trim())return 'El nombre es obligatorio.';if(!form.encargado_id)return 'Seleccione un encargado.';if(!form.telefono.trim()||form.telefono.length>9)return 'El teléfono es obligatorio y admite hasta 9 caracteres.';if(!form.direccion.trim())return 'La dirección es obligatoria.';return ''}
async function save(){const issue=validate();if(issue){error.value=issue;return}saving.value=true;try{await guardarAlmacen(editing.value,{...form});modal.value=false;success.value=`Almacén ${editing.value?'actualizado':'creado'} correctamente.`;await load(editing.value?page.value:1)}catch(e){error.value=message(e)}finally{saving.value=false}}
async function remove(item:Almacen){if(item.documentos_count>0){error.value='No se puede eliminar el almacén porque tiene documentos asociados.';return}if(item.por_defecto){error.value='Asigne otro almacén predeterminado antes de eliminar este registro.';return}if(!confirm(`¿Eliminar el almacén “${item.nombre}”?`))return;try{await eliminarAlmacen(item.id);success.value='Almacén eliminado correctamente.';await load(page.value)}catch(e){error.value=message(e)}}
const message=(e:unknown)=>e instanceof Error?e.message:'No se pudo completar la operación.';onMounted(()=>load())
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / Administración / Almacén / Almacenes</nav><header class="hero"><div class="mark">AL</div><div><small>MIA · CONFIGURACIÓN</small><h1>Almacenes</h1><p>Administra locales, responsables y el almacén operativo principal.</p></div><b>{{total}} almacenes</b><button @click="open()">+ Agregar almacén</button></header><p v-if="success" class="flash success">✓ {{success}}</p><p v-if="error" class="flash">{{error}}</p><section class="filters"><input v-model.trim="criterio" placeholder="Buscar por nombre de almacén" @keyup.enter="load(1)"><button @click="load(1)">Buscar</button><button class="soft" @click="criterio='';load(1)">Limpiar</button></section><div v-if="loading" class="empty">Cargando almacenes…</div><div v-else-if="!rows.length" class="empty">No se encontraron almacenes registrados.</div>
<section v-else class="cards"><article v-for="item in rows" :key="item.id" :class="{default:item.por_defecto}"><header><div class="icon">{{item.por_defecto?'★':'⌂'}}</div><div><small>{{item.por_defecto?'ALMACÉN PREDETERMINADO':'ALMACÉN'}}</small><h2>{{item.nombre}}</h2></div><span v-if="item.codigo_avalon">{{item.codigo_avalon}}</span></header><dl><div><dt>Encargado</dt><dd>{{item.encargado||'—'}}</dd></div><div><dt>Teléfono</dt><dd>{{item.telefono}}</dd></div><div><dt>Dirección</dt><dd>{{item.direccion}}</dd></div><div><dt>Documentos asociados</dt><dd>{{item.documentos_count}}</dd></div></dl><div v-if="item.por_defecto" class="shortcuts"><RouterLink to="/modulos/administracion/almacen/ingresos">Ver ingresos</RouterLink><RouterLink to="/modulos/administracion/almacen/salidas">Ver salidas</RouterLink></div><footer><button @click="open(item)">Modificar</button><button class="danger" :disabled="item.documentos_count>0||item.por_defecto" @click="remove(item)">Eliminar</button></footer></article></section><footer v-if="lastPage>1" class="pages"><button :disabled="page<=1" @click="load(page-1)">Anterior</button><span>{{page}} / {{lastPage}}</span><button :disabled="page>=lastPage" @click="load(page+1)">Siguiente</button></footer>
<div v-if="modal" class="backdrop" @mousedown.self="modal=false"><form class="dialog" @submit.prevent="save"><header><div><small>DATOS DEL ALMACÉN</small><h2>{{editing?'Modificar':'Registrar'}} almacén</h2></div><button type="button" @click="modal=false">×</button></header><div class="grid"><label>Nombre *<input v-model.trim="form.nombre" maxlength="255"></label><label>Código AVALON<input v-model.trim="form.codigo_avalon"></label><label>Teléfono *<input v-model.trim="form.telefono" maxlength="9"></label><label>Dirección *<input v-model.trim="form.direccion" maxlength="255"></label></div><section class="person"><label>Encargado *<span><input v-model.trim="personSearch" placeholder="DNI o nombre (mínimo 4 caracteres)" @keyup.enter.prevent="searchPeople"><button type="button" @click="searchPeople">Buscar</button></span></label><button v-for="person in people" :key="person.id" type="button" class="result" @click="choose(person)"><b>{{person.nombre}}</b><span>{{person.identificador}}</span></button><p v-if="selectedPerson">Seleccionado: <b>{{selectedPerson.nombre}}</b> {{selectedPerson.identificador}}</p></section><label class="check"><input v-model="form.por_defecto" type="checkbox"> Establecer como almacén predeterminado <small>Se desmarcará automáticamente el almacén principal actual.</small></label><footer><button type="button" class="soft" @click="modal=false">Cancelar</button><button :disabled="saving">{{saving?'Guardando…':'Guardar almacén'}}</button></footer></form></div></div></template>
<style scoped>
