 #edf0f1;font-size:.52rem}.cards dt{color:#75838a}.cards dd{margin-left:auto;text-align:right}.shortcuts{display:flex;gap:5px}.shortcuts a{padding:5px;border-radius:5px;color:#277254;background:#e7f7ef;text-decoration:none;font-size:.48rem}.cards footer{margin-top:10px;display:flex}.cards footer button{border:0;color:var(--accent);background:none;font-size:.5rem}.cards footer .danger{margin-left:auto;color:#b93f46}.cards footer button:disabled{color:#adb5b8}.pages{margin-top:12px;display:flex;justify-content:center;align-items:center;gap:8px;font-size:.52rem}.backdrop{position:fixed;z-index:100;inset:0;padding:20px;display:grid;place-items:center;background:#172b3d88}.dialog{width:min(700px,100%);padding:20px;box-sizing:border-box;border-radius:12px;background:#fff}.dialog>header{display:flex}.dialog h2{margin:2px 0 13px;font-size:1rem}.dialog>header button{margin-left:auto;color:#59666c;background:none;font-size:1.2rem}.grid{display:grid;grid-template-columns:1fr 1fr;gap:8px}.dialog label{font-size:.52rem}.dialog label input{margin-top:4px}.person{margin:11px 0;padding:10px;border-radius:8px;background:#f5f7f8}.person label span{display:flex;gap:5px}.result{width:100%;margin-top:5px;display:flex!important;text-align:left;color:#46555c!important;background:#fff!important;border:1px solid #e0e5e7!important}.result span{margin-left:auto}.person p{font-size:.53rem}.check{display:flex;align-items:center;gap:6px}.check input{width:auto;margin:0!important}.check small{margin-left:auto}.dialog>footer{margin-top:13px;display:flex;justify-content:flex-end;gap:6px}@media(max-width:850px){.hero{flex-wrap:wrap}.hero>b{margin-left:0}.cards,.grid{grid-template-columns:1fr}}
